// Parse the inline `[a, b, ...]` payload of a flow list, dropping comments
// and blank entries, unquoting each item.
function flowItems(inline) {
    var flow = inline.replace(/^\[[ \t]*/, '').replace(/[ \t]*\].*$/, '');
    var parts = flow === '' ? [] : flow.split(',');
